spec.setup_code:
var A = new api.THREE.Vector3(2, 0, 0);
var origin = new api.THREE.Vector3(0, 0, 0);
var arrowA = new api.THREE.ArrowHelper(A.clone().normalize(), origin, A.length(), 0x4C72B0);
var arrowB = new api.THREE.ArrowHelper(new api.THREE.Vector3(1, 0, 0), origin, 1.5, 0xE8593C);
var arrowR = new api.THREE.ArrowHelper(new api.THREE.Vector3(0, 0, 1), origin, 1, 0x2E7D32);
api.group.add(arrowA);
api.group.add(arrowB);
api.group.add(arrowR);
return {
  update: function(t) {
    var theta = (t * 0.005) % Math.PI;
    var B = new api.THREE.Vector3(1.5 * Math.cos(theta), 1.5 * Math.sin(theta), 0);
    arrowB.setDirection(B.clone().normalize());
    arrowB.setLength(Math.max(B.length(), 0.01));
    var R = new api.THREE.Vector3().crossVectors(A, B);
    var mag = R.length();
    if (mag > 0.001) {
      arrowR.setDirection(R.clone().normalize());
      arrowR.setLength(mag);
    }
  }
};

return {
  draw: function(ctx, W, H, t, dt) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    function arrow(x0, y0, x1, y1, color) {
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.lineTo(x1, y1);
      ctx.stroke();
      var ang = Math.atan2(y1 - y0, x1 - x0);
      var hs = 10;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x1 - hs * Math.cos(ang - Math.PI / 6), y1 - hs * Math.sin(ang - Math.PI / 6));
      ctx.lineTo(x1 - hs * Math.cos(ang + Math.PI / 6), y1 - hs * Math.sin(ang + Math.PI / 6));
      ctx.closePath();
      ctx.fill();
    }
    var scale = Math.min(W, H) * 0.015;
    var ox = W * 0.3, oy = H * 0.7;
    var Amag = 5, Bmag = 4;
    var theta = (t * 0.005) % Math.PI;
    var ax = Amag * scale, ay = 0;
    var bx = Bmag * scale * Math.cos(theta), by = -Bmag * scale * Math.sin(theta);
    ctx.beginPath();
    ctx.moveTo(ox, oy);
    ctx.lineTo(ox + ax, oy + ay);
    ctx.lineTo(ox + ax + bx, oy + ay + by);
    ctx.lineTo(ox + bx, oy + by);
    ctx.closePath();
    ctx.fillStyle = 'rgba(46,125,50,0.25)';
    ctx.fill();
    arrow(ox, oy, ox + ax, oy + ay, '#4C72B0');
    arrow(ox, oy, ox + bx, oy + by, '#E8593C');
    var cross = Amag * Bmag * Math.sin(theta);
    ctx.fillStyle = '#333';
    ctx.font = '15px sans-serif';
    ctx.fillText('|A x B| = ' + cross.toFixed(1) + ' (shaded area, points out of the page)', 10, H - 15);
  }
};
